# Hostile file names (Review Focus 1). Records what Rails does with each:
# Document.normalize_filename, the Content-Disposition header that send_file
# emits (ActionDispatch::Http::ContentDisposition) and the admin ZIP entry
# name; also emits I18n's transliteration table used by that header.
#
# This generator reads app/models/document.rb (and config/environment when
# WITH_APP=1). Those paths exist only on the local tag rails-final, not in
# this tree. Check that tag out in another worktree, then run:
#
#   bundle exec ruby rust/ged/tests/fixtures/gen_filename_corpus.rb
require "json"
require "i18n"
require "action_dispatch"
require "action_dispatch/http/content_disposition"
require "active_record"
require_relative "../../../../config/environment" if ENV["WITH_APP"]

# Document.normalize_filename without booting the app/DB: load the method body.
src = File.read(File.expand_path("../../../../app/models/document.rb", __dir__))
body = src[/def self\.normalize_filename.*?\n  end\n/m]
raise "normalize_filename not found" unless body
klass = Class.new { class_eval(body) }
normalize = ->(v) { klass.normalize_filename(v) }

ID = "0191a2b3-c4d5-7e6f-8a9b-0c1d2e3f4a5b"
names = [
  "report.pdf", "mon rapport.pdf", "résumé final.pdf", "日本語.pdf", "emoji 😀.png", "Ünïcödé–dash.txt",
  "../../etc/passwd", "..\\..\\windows\\system32\\cmd.exe", "/abs/path/file.txt", "C:\\dir\\file.txt", "a/b/c.txt", "a\\b\\c.txt",
  "...hidden", ".bashrc", "..", ".", "", "   ", "\u0000", "a\u0000b.txt", "file\nname.txt", "file\r\nSet-Cookie: x=1", "evil\r\nContent-Length: 0\r\n\r\n<html>",
  "tab\there.txt", "del\u007Fchar", "quote\"inside.txt", "semi;colon.txt", "back`tick", "per%cent.txt", "dollar$sign", "pipe|name", "star*.txt", "q?.txt",
  "lt<gt>.txt", "colon:name.txt", "comma, name.txt", "a'b.txt", "filename=\"x\".pdf", "x\"; filename*=UTF-8''evil.exe", "name\u202Eexe.txt", "\u2028line", "trailing space ", " leading",
  "/", "///", "a/", "dir/", "a" * 300 + ".pdf", "ß.txt", "ŉ.txt", "Ǭ.txt", "ʼn", "naïve café.docx", "COM1", "con.txt", "-rf", "~/x", "a..b", "a.", ".a.", "x" * 5,
]
cases = names.map do |name|
  n = normalize.(name)
  {
    input: name,
    normalized: n,
    attachment: ActionDispatch::Http::ContentDisposition.format(disposition: :attachment, filename: n),
    inline: ActionDispatch::Http::ContentDisposition.format(disposition: :inline, filename: n),
    zip_entry: "#{ID}-#{n}",
  }
end
File.write(File.expand_path("filename_corpus.json", __dir__), JSON.pretty_generate({ id: ID, cases: cases }) + "\n")

approx = I18n::Backend::Transliterator::HashTransliterator::DEFAULT_APPROXIMATIONS
rows = approx.sort.map { |k, v| "    (#{k.inspect}, #{v.inspect})," }
File.write(File.expand_path("../../src/storage/transliteration_table.rs", __dir__), <<~RS)
  // @generated by tests/fixtures/gen_filename_corpus.rb from i18n #{I18n::VERSION}. Do not edit.

  /// `I18n::Backend::Transliterator::HashTransliterator::DEFAULT_APPROXIMATIONS`,
  /// sorted by character for binary search.
  pub static APPROXIMATIONS: &[(&str, &str)] = &[
  #{rows.join("\n")}
  ];
RS
puts "wrote #{cases.size} cases, #{rows.size} approximations (i18n #{I18n::VERSION})"
